                    i += 1
    if i < n and tokens[i] == "END":
        i += 1
    if i < n and tokens[i] == name:
        i += 1
    return vr, i

def build_spacing_table(layer):
    if "spacing_table" in layer:
        return layer["spacing_table"]
    spacings = layer.get("spacings", [])
    if spacings:
        return {"spacing": spacings[0]["value"]}
    return None

def parse_lef(path):
    with open(path, "r", encoding="utf-8", errors="replace") as fh:
        text = fh.read()
    tokens = tokenize(text)
    n = len(tokens)
    i = 0
    layers = {}
    vias = []
    viarules = []
    while i < n:
        tok = tokens[i]
        if tok == "LAYER":
            layer, i = parse_layer(tokens, i + 1)
            layers[layer["name"]] = layer
        elif tok == "VIA":
            via, i = parse_via(tokens, i + 1)
            vias.append(via)
        elif tok == "VIARULE":
            vr, i = parse_viarule(tokens, i + 1)
            viarules.append(vr)
        elif tok == "PROPERTYDEFINITIONS":
            while i < n and not (tokens[i] == "END" and i + 1 < n and tokens[i + 1] == "PROPERTYDEFINITIONS"):
                i += 1
            i += 2
        else:
            i += 1
    cut_names = {name for name, l in layers.items() if l.get("type") == "CUT"}
    routing = []
    for name, l in layers.items():
        if l.get("type") != "ROUTING":
            continue
        routing.append({"name": name, "direction": l.get("direction"), "width": l.get("width"),
                        "pitch": l.get("pitch"), "max_width": l.get("max_width"), "area": l.get("area"),
                        "offset": l.get("offset"), "spacing_table": build_spacing_table(l)})
    cuts = []
    for name, l in layers.items():
        if l.get("type") != "CUT":
            continue
        spacing = None
        adjacent = None
        for sp in l.get("spacings", []):
            if "adjacent_cuts" in sp:
                adjacent = {"spacing": sp["value"], "adjacent_cuts": sp["adjacent_cuts"], "within": sp.get("within")}
            elif spacing is None:
                spacing = sp["value"]
        cuts.append({"name": name, "spacing": spacing, "adjacent_cuts_spacing": adjacent})
    vias_out = []
    for v in vias:
        c = 0
        for lname, rects in v.get("_rects", {}).items():
            if lname in cut_names:
                c += len(rects)
        vias_out.append({"name": v["name"], "cuts": c, "resistance": v["resistance"], "layers": v["layers"]})
    return {"routing_layers": routing, "cut_layers": cuts, "vias": vias_out, "viarules": viarules}

